using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalNaturalSurfaceTuning{
static FinalNaturalSurfaceTuning(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalNaturalSurfaceTuning.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("FinalNaturalSurfaceTuning.request");Run();}
static T F<T>(object o,string n)=>(T)o.GetType().GetField(n).GetValue(o);static object Read(MeshFilter f)=>typeof(FinalCitywideStops).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f});
static void Run(){var log=new StringBuilder();try{
var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");if(!scene.isLoaded)throw new Exception("Target scene not loaded");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");string backup="FinalEnvironmentRoadBackup/NaturalSurfaceTuning-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Directory.CreateDirectory(backup);
foreach(var path in new[]{"Assets/Scenes/Oasis/RoadAtlas/Road Atlas.mat","Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Markings.mat"}){File.Copy(path,backup+"/"+Path.GetFileName(path));var mat=AssetDatabase.LoadAssetAtPath<Material>(path);var st=mat.GetVector("_Road3ST");st.y=.25f;mat.SetVector("_Road3ST",st);EditorUtility.SetDirty(mat);}
var atlas=new Texture2D(2,2,TextureFormat.RGBA32,false);atlas.LoadImage(File.ReadAllBytes("Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City Road Detail Atlas.png"));var pixels=atlas.GetPixels32();int aw=atlas.width,ah=atlas.height;UnityEngine.Object.DestroyImmediate(atlas);
Func<Vector4,float,float> Alpha=(m,o)=>{int tile=Mathf.FloorToInt(m.x/32);float u=.023f+.954f*Mathf.Clamp01(m.x-tile*32-16),v=.023f+.954f*Mathf.Repeat(m.y+o,1);if(tile==0&&((Mathf.Abs(u-.342f)<.07&&Mathf.Abs(v-.326f)<.07)||(Mathf.Abs(u-.664f)<.07&&Mathf.Abs(v-.674f)<.07))&&Mathf.Floor(m.y+o)!=Mathf.Floor(Mathf.Round(m.w)*.5f))return 0;int x=Mathf.Clamp((int)((tile%4+u)/4*aw),0,aw-1),y=Mathf.Clamp((int)((3-tile/4+v)/4*ah),0,ah-1);return pixels[y*aw+x].a/255f;};
int changed=0,total=0;float oldTotal=0,newTotal=0;var processed=new HashSet<Mesh>();
foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){var r=f.GetComponent<Renderer>();if(!f.sharedMesh||!r||!r.sharedMaterial||r.sharedMaterial.name!="City PNG Markings"||!processed.Add(f.sharedMesh))continue;var d=Read(f);int layer=F<int>(d,"layer"),tile=F<int>(d,"tile");if((layer!=0&&layer!=2)||!(tile==0||tile==2||tile==4||tile==5))continue;var uv=F<Vector2[]>(d,"uv");var mark=F<Vector4[]>(d,"mark");var site=F<Vector4[]>(d,"site");var ids=F<int[]>(d,"ids");var p=F<Vector3[]>(d,"p");var samples=new List<Vector4>();var keys=new HashSet<string>();float cx=layer==0?.334f:.611f,cy=layer==0?.497f:.349f;
for(int k=0;k<ids.Length;k+=3){int ia=ids[k],ib=ids[k+1],ic=ids[k+2];if(Mathf.Abs(Vector3.Cross(p[ib]-p[ia],p[ic]-p[ia]).y)<=.0001f)continue;var a=uv[ia];var b=uv[ib]-a;var c=uv[ic]-a;float det=b.x*c.y-b.y*c.x;if(Mathf.Abs(det)<1e-6)continue;int min=Mathf.CeilToInt(Mathf.Min(a.y,Mathf.Min(uv[ib].y,uv[ic].y))-cy-.036f),max=Mathf.FloorToInt(Mathf.Max(a.y,Mathf.Max(uv[ib].y,uv[ic].y))-cy+.036f);
for(int nx=Mathf.CeilToInt(Mathf.Min(a.x,Mathf.Min(uv[ib].x,uv[ic].x))-cx-.036f);nx<=Mathf.FloorToInt(Mathf.Max(a.x,Mathf.Max(uv[ib].x,uv[ic].x))-cx+.036f);nx++)for(int n=min;n<=max;n++)for(int s=0;s<9;s++){float angle=(s-1)*Mathf.PI/4;var q=new Vector2(nx+cx+(s==0?0:Mathf.Cos(angle)*.036f),n+cy+(s==0?0:Mathf.Sin(angle)*.036f))-a;float x=(q.x*c.y-q.y*c.x)/det,y=(b.x*q.y-b.y*q.x)/det;if(x<-.0001||y<-.0001||x+y>1.0001)continue;var m=mark[ia]+x*(mark[ib]-mark[ia])+y*(mark[ic]-mark[ia]);if(site!=null){var v=site[ia]+x*(site[ib]-site[ia])+y*(site[ic]-site[ia]);if(v.w<-.5&&v.x>=0&&v.x<=1&&v.y>=0&&v.y<=1)continue;}if(keys.Add(nx+":"+n+":"+s))samples.Add(m);}}
log.AppendLine("AUDIT "+f.name+" layer="+layer+" tile="+tile+" uv="+uv.Min(v=>v.x)+","+uv.Max(v=>v.x)+" y="+uv.Min(v=>v.y)+","+uv.Max(v=>v.y)+" samples="+samples.Count);if(samples.Count==0)continue;total++;Func<float,float> Score=o=>samples.Sum(v=>Alpha(v,o));float oldScore=Score(0),bestScore=oldScore,best=0;for(int step=1;step<=99;step++)foreach(int sign in new[]{-1,1}){float phase=step*.005f*sign,score=Score(phase);if(score<bestScore-.01f){bestScore=score;best=phase;}}
float pivot=(mark.Min(v=>v.y)+mark.Max(v=>v.y))*.5f,bestScale=1; if(bestScore>.01f)for(int size=1;size<=20;size++)foreach(int side in new[]{-1,1}){float scale=1+size*.005f*side;for(int phaseStep=-99;phaseStep<=99;phaseStep++){float phase=phaseStep*.005f;float score=samples.Sum(v=>Alpha(new Vector4(v.x,pivot+(v.y-pivot)*scale,v.z,v.w),phase));if(score<bestScore-.01f){bestScore=score;best=phase;bestScale=scale;}}if(bestScore<.01f)break;} oldTotal+=oldScore;newTotal+=bestScore;if(Mathf.Abs(best)>.0001f||Mathf.Abs(bestScale-1)>.0001f){var mesh=f.sharedMesh;string path=AssetDatabase.GetAssetPath(mesh);if(!path.StartsWith("Assets/Scenes/Oasis/FinalEnvironmentRoads/"))throw new Exception("Unexpected mesh "+path);File.Copy(path,backup+"/"+Path.GetFileName(path));var copy=UnityEngine.Object.Instantiate(mesh);copy.SetUVs(3,mark.Select(v=>new Vector4(v.x,pivot+(v.y-pivot)*bestScale+best,v.z,v.w)).ToList());EditorUtility.CopySerialized(copy,mesh);UnityEngine.Object.DestroyImmediate(copy);EditorUtility.SetDirty(mesh);var check=Read(f);if(!F<Vector3[]>(check,"p").SequenceEqual(p)||!F<Vector2[]>(check,"uv").SequenceEqual(uv)||(site!=null&&!F<Vector4[]>(check,"site").SequenceEqual(site)))throw new Exception("Geometry or stamp UV changed");changed++;log.AppendLine(f.name+" phase="+best+" longitudinal scale="+bestScale+" overlaps "+oldScore+" -> "+bestScore);}}
foreach(var f in root.GetComponentsInChildren<MeshFilter>(true))if(f.sharedMesh&&processed.Contains(f.sharedMesh)){var data=Read(f);var values=F<Vector4[]>(data,"mark");if(values!=null&&f.sharedMesh.isReadable){f.sharedMesh.SetUVs(3,values.ToList());EditorUtility.SetDirty(f.sharedMesh);}log.AppendLine("GPU refresh "+f.name+" readable="+f.sharedMesh.isReadable);} AssetDatabase.SaveAssets();log.AppendLine("SUCCESS: assessed "+total+" meshes; shifted "+changed+" PNG layouts ahead/behind; overlap sample total "+oldTotal+" -> "+newTotal+". Geometry, collider references, base UVs and bus/no-parking stamps unchanged. Pavement scale .25 in both existing materials. Backup="+backup);File.WriteAllText("FinalBakedSurfaceTextures.request","repack");
}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/NaturalSurfaceTuningReport.txt",log.ToString());}}
